// ===== Booking rules: edit here =====
const CFG = {
  tz: 'America/New_York',
  workdays: [1, 2, 3, 4, 5], // Mon=1 ... Sun=7
  openTime: '09:00',
  closeTime: '17:00', // Calls must end by this time
  bufferMinutes: 15,
  minNoticeHours: 4,
  maxDaysOut: 30,
  noChangesWithinHours: 24,
  slotStepMinutes: 30,
  allowedDurations: [30, 60],
  defaultDuration: 30,
  maxRangeDays: 7,
  alternativesDaysAhead: 3,
  meetingTitle: 'AdvancedAI.tech Discovery Call',
  tag: 'AdvancedAI.tech Receptionist',
};
// ====================================

const raw = $input.first().json;
const body =
  raw.body && typeof raw.body === 'object'
    ? raw.body
    : raw;

const action = String(body.action || '')
  .trim()
  .toLowerCase();

const now = DateTime.now().setZone(CFG.tz);
const errors = [];

const clean = value =>
  value === undefined || value === null
    ? ''
    : String(value).trim();

const esc = value =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// ===== DATE AND TIME HELPERS =====

function parseDate(value) {
  const text = clean(value);

  if (!text) return null;

  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (!match) return null;

  const date = DateTime.fromISO(
    `${match[1]}-${match[2]}-${match[3]}`,
    { zone: CFG.tz }
  );

  return date.isValid
    ? date.startOf('day')
    : null;
}

// Parses a full ISO timestamp (e.g. 2026-10-27T09:00:00).
// Timestamps without an offset are treated as Eastern.
function parseDateTime(value) {
  const text = clean(value);

  if (!/^\d{4}-\d{2}-\d{2}T\d{1,2}:\d{2}/.test(text)) {
    return null;
  }

  const dt = DateTime.fromISO(text, { zone: CFG.tz });

  return dt.isValid
    ? dt.setZone(CFG.tz).set({
        second: 0,
        millisecond: 0,
      })
    : null;
}

function parseTime(value) {
  const text = clean(value)
    .toLowerCase()
    .replace(/\./g, '')
    .replace(/\s+/g, ' ');

  const match = text.match(
    /^(\d{1,2})(?::?(\d{2}))?\s?(am|pm|a|p)?$/
  );

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const period = match[3];

  if (period) {
    if (hour < 1 || hour > 12) return null;

    if (period[0] === 'p' && hour !== 12) {
      hour += 12;
    }

    if (period[0] === 'a' && hour === 12) {
      hour = 0;
    }
  }

  if (hour > 23 || minute > 59) {
    return null;
  }

  return {
    h: hour,
    mi: minute,
  };
}

function parseStart(input) {
  // Accept a complete ISO timestamp.
  const fullStart = parseDateTime(input.start);

  if (fullStart) {
    return fullStart;
  }

  // Accept either "time" or "start_time".
  const date = parseDate(input.date);

  const time = parseTime(
    input.time || input.start_time
  );

  if (!date || !time) {
    return null;
  }

  return date.set({
    hour: time.h,
    minute: time.mi,
    second: 0,
    millisecond: 0,
  });
}

// ===== NORMALIZE COMMON FIELDS =====

let duration = parseInt(
  body.duration_minutes ?? body.duration,
  10
);

if (!CFG.allowedDurations.includes(duration)) {
  duration = CFG.defaultDuration;
}

// Accept both the original and webhook field names.
const name = clean(
  body.name || body.caller_name
);

const email = clean(body.email)
  .toLowerCase()
  .replace(/\s+/g, '');

const emailOk =
  /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email);

const phone = clean(body.phone)
  .replace(/\D/g, '');

const topic = clean(
  body.topic || body.topics
);

const company = clean(body.company);

const eventId = clean(
  body.event_id || body.eventId
);

// Build the event title and replace supported placeholders.
const requestedEventTitle = clean(
  body.event_title || body.eventTitle
);

const eventTitle = (
  requestedEventTitle || CFG.meetingTitle
)
  .replace(/\{caller_name\}/gi, name)
  .replace(/\{name\}/gi, name)
  .replace(/\{company\}/gi, company);

// ===== BASE OUTPUT =====

const out = {
  route: 'invalid',
  action,
  cfg: CFG,
  now: now.toISO(),
  timezone: CFG.tz,
  duration,
  name,
  email,
  phone,
  topic,
  company,
  event_id: eventId,
  event_title: eventTitle,
  safe: {
    name: esc(name),
    email: esc(email),
    phone: esc(phone || 'not given'),
    topic: esc(topic || 'not given'),
    company: esc(company || 'not given'),
    event_title: esc(eventTitle),
  },
};

// ===== ACTION VALIDATION =====

if (action === 'check_availability') {
  // Full timestamps for the search window, if sent.
  const afterDT =
    parseDateTime(body.after) ||
    parseDateTime(body.requested_after);

  const beforeDT =
    parseDateTime(body.before) ||
    parseDateTime(body.requested_before);

  // Date can come from date, start_date, or the after timestamp.
  const from =
    parseDate(body.date) ||
    parseDate(body.start_date) ||
    (afterDT ? afterDT.startOf('day') : null) ||
    (beforeDT ? beforeDT.startOf('day') : null);

  if (!from) {
    errors.push(
      'date is required (YYYY-MM-DD), ' +
      'or after/before as ISO timestamps'
    );
  } else {
    let to =
      parseDate(body.end_date) ||
      (beforeDT ? beforeDT.startOf('day') : null) ||
      from;

    if (to < from) {
      to = from;
    }

    if (
      to.diff(from, 'days').days >
      CFG.maxRangeDays - 1
    ) {
      to = from.plus({
        days: CFG.maxRangeDays - 1,
      });
    }

    out.range_start = from.toISODate();
    out.range_end = to.toISODate();
    out.timeMin = from.toISO();
    out.timeMax = to.endOf('day').toISO();

    // Optional time window: full timestamps win,
    // otherwise fall back to plain time fields.
    if (afterDT) {
      out.requested_after = afterDT.toISO();
    } else {
      const requestedAfterTime = parseTime(
        body.after_time ||
        body.requested_after ||
        body.start_time ||
        body.time
      );

      if (requestedAfterTime) {
        out.requested_after = from
          .set({
            hour: requestedAfterTime.h,
            minute: requestedAfterTime.mi,
            second: 0,
            millisecond: 0,
          })
          .toISO();
      }
    }

    if (beforeDT) {
      out.requested_before = beforeDT.toISO();
    } else {
      const requestedBeforeTime = parseTime(
        body.before_time ||
        body.requested_before ||
        body.end_time
      );

      if (requestedBeforeTime) {
        out.requested_before = to
          .set({
            hour: requestedBeforeTime.h,
            minute: requestedBeforeTime.mi,
            second: 0,
            millisecond: 0,
          })
          .toISO();
      }
    }
  }
} else if (action === 'find_booking') {
  if (!email && !phone && !name) {
    errors.push(
      'email, phone, or name is required'
    );
  }

  out.query = email || phone || name;

  out.timeMin = now
    .minus({ hours: 1 })
    .toISO();

  out.timeMax = now
    .plus({
      days: CFG.maxDaysOut + 30,
    })
    .toISO();
} else if (
  action === 'book' ||
  action === 'reschedule'
) {
  const start = parseStart(body);

  if (!start) {
    errors.push(
      'date (YYYY-MM-DD) and time/start_time ' +
      '(HH:MM, Eastern) are required'
    );
  }

  if (action === 'book') {
    if (!name) {
      errors.push('name or caller_name is required');
    }
  } else if (!eventId) {
    errors.push(
      'event_id is required (get it from find_booking)'
    );
  }

  if (!emailOk) {
    errors.push('a valid email is required');
  }

  if (start) {
    const end = start.plus({
      minutes: duration,
    });

    out.start = start.toISO();
    out.end = end.toISO();

    out.timeMin = start
      .startOf('day')
      .toISO();

    out.timeMax = start
      .plus({
        days: CFG.alternativesDaysAhead,
      })
      .endOf('day')
      .toISO();
  }
} else if (action === 'cancel') {
  if (!eventId) {
    errors.push(
      'event_id is required (get it from find_booking)'
    );
  }

  if (!emailOk) {
    errors.push('a valid email is required');
  }
} else {
  errors.push(
    'unknown action; use check_availability, ' +
    'find_booking, book, reschedule, or cancel'
  );
}

// ===== RESPONSE =====

out.errors = errors;

if (errors.length === 0) {
  out.route = action;

  out.response = {
    status: 'ok',
    errors: [],
    message: 'Request normalized successfully.',
  };
} else {
  // out.route = 'invalid';
  out.route = action;

  out.response = {
    status: 'invalid_request',
    errors,
    message:
      'Missing or unclear details: ' +
      errors.join('; ') +
      '.',
  };
}

return [{ json: out }];

// ---- shared slot helpers (same in Check Slot / Check Reschedule) ----
function hm(str, day) { const [h, m] = str.split(':').map(Number); return day.set({ hour: h, minute: m, second: 0, millisecond: 0 }); }
function collectBusy(items, tz) {
  const busy = [];
  for (const it of items) {
    const e = it.json || {};
    if (!e.id || e.error || e.status === 'cancelled' || e.transparency === 'transparent') continue;
    if ((e.attendees || []).some(a => a.self && a.responseStatus === 'declined')) continue;
    let s, en;
    if (e.start && e.start.dateTime) { s = DateTime.fromISO(e.start.dateTime).setZone(tz); en = DateTime.fromISO(e.end.dateTime).setZone(tz); }
    else if (e.start && e.start.date) { s = DateTime.fromISO(e.start.date, { zone: tz }); en = DateTime.fromISO(e.end.date, { zone: tz }); }
    else continue;
    busy.push({ s, e: en, id: e.id });
  }
  return busy;
}
function slotProblem(start, dur, busy, C, now, excludeId) {
  const end = start.plus({ minutes: dur });
  const day = start.startOf('day');
  if (!C.workdays.includes(start.weekday) || start < hm(C.openTime, day) || end > hm(C.closeTime, day)) return 'outside_hours';
  if (start < now.plus({ hours: C.minNoticeHours })) return 'too_soon';
  if (start > now.plus({ days: C.maxDaysOut })) return 'too_far_out';
  const b = C.bufferMinutes;
  if (busy.some(x => x.id !== excludeId && x.s < end.plus({ minutes: b }) && x.e > start.minus({ minutes: b }))) return 'conflict';
  return null;
}
function freeSlots(fromDay, toDay, dur, busy, C, now, excludeId) {
  const days = [];
  for (let d = fromDay.startOf('day'); d <= toDay; d = d.plus({ days: 1 })) {
    if (!C.workdays.includes(d.weekday)) continue;
    const times = [];
    for (let t = hm(C.openTime, d); t.plus({ minutes: dur }) <= hm(C.closeTime, d); t = t.plus({ minutes: C.slotStepMinutes })) {
      if (!slotProblem(t, dur, busy, C, now, excludeId)) times.push(t);
    }
    days.push({ date: d.toISODate(), day_label: d.toFormat('cccc, LLLL d'), open_times: times.map(t => t.toFormat('h:mm a')), open_times_24h: times.map(t => t.toFormat('HH:mm')) });
  }
  return days;
}
// ---------------------------------------------------------------------
const n = $('Normalize').first().json; const C = n.cfg;
const now = DateTime.fromISO(n.now).setZone(C.tz);
const busy = collectBusy($input.all(), C.tz);
const from = DateTime.fromISO(n.range_start, { zone: C.tz });
const to = DateTime.fromISO(n.range_end, { zone: C.tz });
const days = freeSlots(from, to, n.duration, busy, C, now);
const total = days.reduce((a, d) => a + d.open_times.length, 0);
const message = total
  ? days.filter(d => d.open_times.length).map(d => d.day_label + ': ' + d.open_times.slice(0, 6).join(', ') + (d.open_times.length > 6 ? ', and more' : '')).join('. ') + '.'
  : 'No open times in that range. Calls run weekdays 9 AM to 5 PM Eastern, need at least 4 hours notice, and can be booked up to 30 days out.';
return [{ json: { response: { status: total ? 'ok' : 'no_availability', timezone: 'America/New_York', duration_minutes: n.duration, days, message } } }];

const n = $('Normalize').first().json; const C = n.cfg;
const now = DateTime.fromISO(n.now).setZone(C.tz);
const bookings = [];
for (const it of $input.all()) {
  const e = it.json || {};
  if (!e.id || e.status === 'cancelled' || !(e.description || '').includes(C.tag)) continue;
  if (!e.start || !e.start.dateTime) continue;
  const s = DateTime.fromISO(e.start.dateTime).setZone(C.tz);
  if (s < now) continue;
  const pending = (e.summary || '').startsWith('[PENDING]');
  bookings.push({ event_id: e.id, when: s.toFormat(`cccc, LLLL d 'at' h:mm a`), date: s.toISODate(), time: s.toFormat('HH:mm'), status: pending ? 'pending_approval' : 'confirmed', can_change_by_phone: s > now.plus({ hours: C.noChangesWithinHours }) });
}
const message = bookings.length
  ? 'Upcoming bookings: ' + bookings.map(b => b.when + (b.status === 'pending_approval' ? `, waiting on Robert's approval` : ', confirmed')).join('; ') + '.'
  : 'No upcoming bookings found for that caller.';
return [{ json: { response: { status: bookings.length ? 'found' : 'not_found', bookings, message } } }];

// ---- shared slot helpers (same in Compute Slots / Check Reschedule) ----
function hm(str, day) { const [h, m] = str.split(':').map(Number); return day.set({ hour: h, minute: m, second: 0, millisecond: 0 }); }
