      if (!slotProblem(t, dur, busy, C, now, excludeId)) times.push(t);
    }
    days.push({ date: d.toISODate(), day_label: d.toFormat('cccc, LLLL d'), open_times: times.map(t => t.toFormat('h:mm a')), open_times_24h: times.map(t => t.toFormat('HH:mm')) });
  }
  return days;
}
const REASONS = { outside_hours: 'That time is outside call hours, weekdays 9 AM to 5 PM Eastern.', too_soon: 'Calls need at least 4 hours notice.', too_far_out: 'Calls can only be booked up to 30 days out.', conflict: 'That time is already taken.' };
function altList(days, max) { return days.flatMap(d => d.open_times_24h.map((t, i) => ({ date: d.date, time: t, spoken: d.day_label + ' at ' + d.open_times[i] }))).slice(0, max); }
// ---------------------------------------------------------------------
const n = $('Normalize').first().json; const C = n.cfg;
const now = DateTime.fromISO(n.now).setZone(C.tz);
const busy = collectBusy($input.all(), C.tz);
const start = DateTime.fromISO(n.start).setZone(C.tz);
const end = start.plus({ minutes: n.duration });
const when = start.toFormat(`cccc, LLLL d 'at' h:mm a`);
const problem = slotProblem(start, n.duration, busy, C, now);
if (!problem) {
  return [{ json: { ok: true, start: start.toISO(), end: end.toISO(), when,
    pending_response: { status: 'pending_approval', when, message: `Request sent to Robert for ${when} Eastern. Once he approves, a calendar invite with a Google Meet link goes to ${n.email}.` } } }];
