// ===== Booking rules: edit here =====
const CFG = {
  tz: 'America/New_York',
  workdays: [1, 2, 3, 4, 5], // Mon=1 ... Sun=7
  openTime: '09:00',
  closeTime: '17:00', // Calls must end by this time
  bufferMinutes: 15,
  minNoticeHours: 4,
  maxDaysOut: 30,
  noChangesWithinHours: 24,
  slotStepMinutes: 30,
  allowedDurations: [30, 60],
  defaultDuration: 30,
  maxRangeDays: 7,
  alternativesDaysAhead: 3,
  meetingTitle: 'AdvancedAI.tech Discovery Call',
  tag: 'AdvancedAI.tech Receptionist',
};
// ====================================

const raw = $input.first().json;
const body =
  raw.body && typeof raw.body === 'object'
    ? raw.body
    : raw;

const action = String(body.action || '')
  .trim()
  .toLowerCase();

const now = DateTime.now().setZone(CFG.tz);
const errors = [];

const clean = value =>
  value === undefined || value === null
    ? ''
    : String(value).trim();

const esc = value =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// ===== DATE AND TIME HELPERS =====

function parseDate(value) {
  const text = clean(value);

  if (!text) return null;

  const match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (!match) return null;

  const date = DateTime.fromISO(
    `${match[1]}-${match[2]}-${match[3]}`,
    { zone: CFG.tz }
  );

  return date.isValid
    ? date.startOf('day')
    : null;
}

// Parses a full ISO timestamp (e.g. 2026-10-27T09:00:00).
// Timestamps without an offset are treated as Eastern.
function parseDateTime(value) {
  const text = clean(value);

  if (!/^\d{4}-\d{2}-\d{2}T\d{1,2}:\d{2}/.test(text)) {
    return null;
  }

  const dt = DateTime.fromISO(text, { zone: CFG.tz });

  return dt.isValid
    ? dt.setZone(CFG.tz).set({
        second: 0,
        millisecond: 0,
      })
    : null;
}

function parseTime(value) {
  const text = clean(value)
    .toLowerCase()
    .replace(/\./g, '')
    .replace(/\s+/g, ' ');

  const match = text.match(
    /^(\d{1,2})(?::?(\d{2}))?\s?(am|pm|a|p)?$/
  );

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const period = match[3];

  if (period) {
    if (hour < 1 || hour > 12) return null;

    if (period[0] === 'p' && hour !== 12) {
      hour += 12;
    }

    if (period[0] === 'a' && hour === 12) {
      hour = 0;
    }
  }

  if (hour > 23 || minute > 59) {
    return null;
  }

  return {
    h: hour,
    mi: minute,
  };
}

function parseStart(input) {
  // Accept a complete ISO timestamp.
  const fullStart = parseDateTime(input.start);

  if (fullStart) {
    return fullStart;
  }

  // Accept either "time" or "start_time".
  const date = parseDate(input.date);

  const time = parseTime(
    input.time || input.start_time
