) {
  const start = parseStart(body);

  if (!start) {
    errors.push(
      'date (YYYY-MM-DD) and time/start_time ' +
      '(HH:MM, Eastern) are required'
    );
  }

  if (action === 'book') {
    if (!name) {
      errors.push('name or caller_name is required');
    }
  } else if (!eventId) {
    errors.push(
      'event_id is required (get it from find_booking)'
    );
  }

  if (!emailOk) {
    errors.push('a valid email is required');
  }

  if (start) {
    const end = start.plus({
      minutes: duration,
    });

