  if (!eventId) {
    errors.push(
      'event_id is required (get it from find_booking)'
    );
  }

  if (!emailOk) {
    errors.push('a valid email is required');
  }
} else {
  errors.push(
    'unknown action; use check_availability, ' +
    'find_booking, book, reschedule, or cancel'
  );
}

// ===== RESPONSE =====

out.errors = errors;

if (errors.length === 0) {
  out.route = action;

  out.response = {
    status: 'ok',
    errors: [],
    message: 'Request normalized successfully.',
  };
} else {
  // out.route = 'invalid';
  out.route = action;

  out.response = {
    status: 'invalid_request',
    errors,
    message:
      'Missing or unclear details: ' +
      errors.join('; ') +
      '.',
  };
}

return [{ json: out }];

